        "ko": "펀드 매니저들이 포트폴리오를 조정함에 따라 뉴욕, 도쿄, 서울의 증권거래소는 신중한 관망세를 보이고 있습니다. 기업들은 대출 금리의 향방이 대규모 인프라 구축과 인공지능 설비 투자에 미칠 영향을 주시하고 있습니다. 다가오는 9월 연준 정책 성명서는 올 하반기 글로벌 자본 시장의 방향타 역할을 할 것입니다.",
