            "en": "It can be accomplished in part by direct recruiting by the Government itself, treating the task as we would treat the emergency of a war.",
            "ko": "정부가 마치 전시 비상사태를 다루듯 직접 채용에 나섬으로써 이를 힘차게 추진할 수 있습니다."
